async function handleListConversations(
  ws: WebSocket,
  store: SessionStore,
  options: MessageHandlerOptions,
  message: {limit?: number; before?: import('../../types/sessionStore.js').SessionCursor}
): Promise<void> {
  const userId = (ws as any).userId;

  if (!options.history?.enabled || !store.listFor) {
