/** Opens a client that sends a ping the moment it connects, resolving with every frame seen up to its pong. */
export async function connectAndSettle(
  url: string,
  outbound?: unknown,
  token = 't'
): Promise<any[]> {
  const client = connectClient(url, token);
  const frames: any[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as any;
      frames.push(frame);
      if (frame.type === 'connected') {
        if (outbound) {
          client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
        }
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      }
      if (frame.type === 'pong') resolve();
    });
  });
  return frames;
}

